QString QgsOpenClUtils::deviceDescription( const QString deviceId )
{
  for ( const auto &dev : devices() )
  {
    if ( QgsOpenClUtils::deviceId( dev ) == deviceId )
      return deviceDescription( dev );
  }
  return QString();
}

